mapper.select:
select cast(p.id as varchar) as post_id,
       p.title,
       p.description as summary,
       p.tags as tags_json,
       p.is_top,
       p.publish_time,
       p.latitude,
       p.longitude
  from know_posts p
 where p.status = 'published'
   and p.visible = 'public'
   and (
        lower(coalesce(p.title, '')) like #{keywordLike}
        or lower(coalesce(p.description, '')) like #{keywordLike}
        or lower(coalesce(p.tags, '')) like #{keywordLike}
   )

   and lower(coalesce(p.tags, '')) like #{tagLike}


   and (
        p.is_top < #{afterIsTop}
        or (
            p.is_top = #{afterIsTop}
            and (
                p.publish_time < #{afterPublishTime}
                or (p.publish_time = #{afterPublishTime} and p.id < #{afterPostId})
            )
        )
   )

 order by p.is_top desc, p.publish_time desc, p.id desc
 limit #{limit}

 offset #{offset}
